using System.Reflection;
using System.Xml;
using AvaloniaEdit.Highlighting;
using AvaloniaEdit.Highlighting.Xshd;
using SproutStudio.Editor;

namespace SproutStudio.Services;

/// <summary>
/// Studio's dark syntax highlighting for every supported language. Definitions are embedded
/// .xshd resources generated by tools/generate-syntax-definitions.py and share one palette, so
/// the code editor, the Academy workspace, and read-only code samples all look the same.
/// </summary>
public static class SyntaxHighlightingRegistry
{
    private static readonly IReadOnlyDictionary<DocumentLanguage, string> ResourceNames = new Dictionary<DocumentLanguage, string>
    {
        [DocumentLanguage.Sprout] = "Sprout",
        [DocumentLanguage.Python] = "Python",
        [DocumentLanguage.Java] = "Java",
        [DocumentLanguage.Rust] = "Rust",
        [DocumentLanguage.Go] = "Go",
        [DocumentLanguage.C] = "C",
        [DocumentLanguage.Cpp] = "Cpp",
        [DocumentLanguage.CSharp] = "CSharp",
        [DocumentLanguage.JavaScript] = "JavaScript",
        [DocumentLanguage.TypeScript] = "TypeScript",
        [DocumentLanguage.Json] = "Json",
        [DocumentLanguage.Toml] = "Toml",
        [DocumentLanguage.Markdown] = "Markdown",
    };

    private static readonly Dictionary<DocumentLanguage, IHighlightingDefinition?> Cache = [];
    private static readonly Lock Gate = new();

    /// <summary>Highlighting for a language, or null for plain text.</summary>
    public static IHighlightingDefinition? For(DocumentLanguage language)
    {
        if (!ResourceNames.TryGetValue(language, out string? name))
        {
            return null;
        }
        lock (Gate)
        {
            if (!Cache.TryGetValue(language, out IHighlightingDefinition? definition))
            {
                definition = Load(name);
                Cache[language] = definition;
            }
            return definition;
        }
    }

    /// <summary>Highlighting for a language registry key such as "python" or a display name such as "Python".</summary>
    public static IHighlightingDefinition? For(string? languageKeyOrName)
    {
        if (string.IsNullOrWhiteSpace(languageKeyOrName))
        {
            return null;
        }
        return LanguageRegistry.TryGet(languageKeyOrName, out LanguageDescriptor? language)
            ? For(language!.Id)
            : LanguageRegistry.All.FirstOrDefault(candidate =>
                string.Equals(candidate.DisplayName, languageKeyOrName, StringComparison.OrdinalIgnoreCase)) is { } named
                ? For(named.Id)
                : null;
    }

    /// <summary>Highlighting for a file path, using the language registry's extension map.</summary>
    public static IHighlightingDefinition? ForPath(string? path)
    {
        string extension = Path.GetExtension(path ?? string.Empty);
        if (string.IsNullOrEmpty(extension))
        {
            return null;
        }
        LanguageDescriptor? language = LanguageRegistry.All.FirstOrDefault(candidate =>
            candidate.Extensions.Contains(extension, StringComparer.OrdinalIgnoreCase));
        return language is null ? null : For(language.Id);
    }

    private static IHighlightingDefinition? Load(string name)
    {
        try
        {
            using Stream? stream = Assembly.GetExecutingAssembly()
                .GetManifestResourceStream($"SproutStudio.Content.Syntax.{name}.xshd");
            if (stream is null)
            {
                return null;
            }
            using XmlReader reader = XmlReader.Create(stream);
            return HighlightingLoader.Load(reader, HighlightingManager.Instance);
        }
        catch (Exception exception) when (exception is XmlException or HighlightingDefinitionInvalidException)
        {
            StudioLog.Error($"Syntax definition {name} could not be loaded.", exception);
            return null;
        }
    }
}
